import db from "../../lib/db";

export default async function handler(req, res) {
  if (req.method !== "POST") {
    return res.status(405).json({ message: "Method not allowed" });
  }

  try {
    const { name, email, mobile, college, category } = req.body;

    if (!name || !email || !mobile || !college || !category) {
      return res.status(400).json({ message: "All fields required" });
    }

    const [result] = await db.query(
      "INSERT INTO students (name, email, mobile, college, category) VALUES (?, ?, ?, ?, ?)",
      [name, email, mobile, college, category]
    );

    res.status(200).json({ success: true, studentId: result.insertId });

  } catch (err) {
    console.error("SAVE STUDENT ERROR FULL:", err); // 🔥 IMPORTANT
    res.status(500).json({ message: err.message });
  }
}